// The source VM below is test-local. The production export has no override ports.
async function harness(extra={}){
 const source=(await fs.readFile(entry,'utf8')).replace(/^import .*;\n/gm,'').replace(/export /g,'').replaceAll('import.meta.url','ENTRY_URL');
 const sandbox={isSemanticLargeProfileStockVersionV3,fs,constants,path,fileURLToPath,createHash,randomBytes,spawn,Buffer,TextDecoder,URL,process,performance,setTimeout,clearTimeout,setInterval,clearInterval,Object,JSON,P,POLICY_SHA,ENTRY_URL:entry.href,...extra};
 return vm.runInNewContext(`(function(){'use strict';${source}\nreturn {runAimockTraceDecoderOwnerV3,parse,parseRss,validateResult,validateIdentity};})()`,sandbox);
}
const id={id:'synthetic-v3',profile:'vercel-ai-sdk',historyCount:1,responseBytes:1,journey:'follow',stockVersion:null,buildSha256:'a'.repeat(64)};
const flags={performance:false,scoringEligibility:false,FPS:null,cpuTime:null};
function invalid(ref){return {schema:P.schemas.decoded,status:'invalid',reason:'timeline-child-raw-join',identity:null,policySha256:POLICY_SHA,rawReference:ref,compressedBytes:null,compressedSha256:null,decodedBytes:null,decodedSha256:null,traceEventCount:null,metadataEventCount:null,emittedCategories:null,rendererMapping:null,costs:null,...flags};}
async function context(t,options={}){
 const root=await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(),'owner-v3-authored-')));t.after(()=>fs.rm(root,{recursive:true,force:true}));await fs.mkdir(path.join(root,id.id));const raw='{}';await fs.writeFile(path.join(root,id.id,P.storage.rawFilename),raw);
 const pin=s=>({dev:String(s.dev),ino:String(s.ino)}),rawReference={path:id.id+'/'+P.storage.rawFilename,bytes:2,sha256:sha(raw)};
 const bridge={artifactRoot:root,rootIdentity:pin(await fs.stat(root,{bigint:true})),caseParentIdentity:pin(await fs.stat(path.join(root,id.id),{bigint:true})),rawReference};
 const calls=[],values=new Map(),stats={pendingOriginals:0,pendingWriters:0,unsafeWriter:false,stopped:false};
 const store={async readJSON(ref,kind){calls.push(['read',ref,kind]);return values.get(ref.path);},stats(){return stats;}};
 const artifacts={reserveDecoderTrafficV3(...args){calls.push(['reserve',args]);},async requireSpaceBeforeDecoderV3(input){calls.push(['space',input]);return bridge;},async writeJSON(name,value,kind){calls.push(['write',name,kind]);const bytes=JSON.stringify(value),ref={path:id.id+'/'+name,bytes:Buffer.byteLength(bytes),sha256:sha(bytes)};values.set(ref.path,plain(value));return ref;},stats(){return stats;}};
 const invocationStarted=performance.now(),caseStarted=performance.now();return {input:{identity:{...id},store,artifacts,caseStarted,invocationStarted},calls,values,bridge,stats,...options};
}
function closed(r){
 assert.deepEqual(Object.keys(r).sort(),['decoderResult','decoderOwner','decoderOriginals'].sort());assert.ok(Object.isFrozen(r)&&Object.isFrozen(r.decoderOwner));
 assert.equal(r.decoderOwner.schema,P.schemas.owner);assert.deepEqual(Object.fromEntries(Object.keys(flags).map(k=>[k,r.decoderOwner[k]])),flags);assert.ok(Buffer.byteLength(JSON.stringify(r.decoderOwner))<=16384);
}
test('fixed actual child and actual owned-PID ps close and publish originals through outer readJSON',async t=>{
 const c=await context(t),api=await import(entry),r=await api.runAimockTraceDecoderOwnerV3(c.input);closed(r);assert.equal(r.decoderOwner.status,'complete',JSON.stringify(r));assert.equal(r.decoderResult.status,'invalid');assert.equal(r.decoderOwner.unsafeOutstanding,false);assert.deepEqual(r.decoderOwner.originalsReference,r.decoderOriginals);
 assert.equal(c.calls.filter(x=>x[0]==='reserve').length,1);assert.deepEqual(c.calls[0],['reserve',[]]);assert.deepEqual(c.calls[1],['space',{caseStarted:c.input.caseStarted,invocationStarted:c.input.invocationStarted}]);assert.equal(c.calls.filter(x=>x[0]==='write').length,1);assert.equal(c.calls.filter(x=>x[0]==='read').length,1);assert.deepEqual(c.calls.at(-1).at(-1),{kind:'evidence'});
 const o=c.values.get(r.decoderOriginals.path);assert.equal(o.schema,P.schemas.originals);assert.ok(Buffer.byteLength(JSON.stringify(o))<=1048576);assert.ok(o.decoder.pid>0);assert.equal(o.decoder.parentPid,process.pid);assert.equal(o.decoder.spawn.status,'fulfilled');assert.equal(o.decoder.exit.code,0);assert.equal(o.decoder.close.code,0);assert.ok(o.decoder.startWitness);assert.equal(o.unsafeOutstanding,false);
 for(const x of [o.decoder,...o.queries]){for(const s of ['stdin','stdout','stderr']){assert.equal(x[s].status,'fulfilled',s);assert.ok(x[s].closeMs!==null,s);assert.ok(x[s].completeSha256,s);}assert.equal(x.spawn.status,'fulfilled');assert.equal(x.exit.status,'fulfilled');assert.equal(x.close.status,'fulfilled');assert.equal(x.attention.status,'fulfilled');}
 assert.equal(r.decoderOwner.rss.initialSeen,true);assert.equal(r.decoderOwner.rss.terminalSeen,true);assert.equal(r.decoderOwner.rss.rejected,0);assert.equal(r.decoderOwner.rss.missed,0);assert.equal(r.decoderOwner.rss.pending,0);assert.equal(r.decoderOwner.rss.samples[0][0],0);assert.equal(r.decoderOwner.rss.samples.at(-1)[0],2);assert.ok(r.decoderOwner.clock.originalsClosedMs<r.decoderOwner.clock.successDeadlineMs);
 console.log('owner-originals',JSON.stringify({clock:r.decoderOwner.clock,decoder:o.decoder,queries:o.queries}));
});
for(const [label,mutate]of [['unknown-profile',x=>x.identity.profile='unknown'],['stock-mismatch',x=>x.identity.stockVersion='0.3.6'],['extra-input',x=>x.options={}],['future-case',x=>x.caseStarted=performance.now()+10000]])test('argument refusal '+label+' performs no reservation',async t=>{const c=await context(t);mutate(c.input);const {runAimockTraceDecoderOwnerV3:run}=await import(entry);await assert.rejects(run(c.input),/timeline-owner-arguments/);assert.equal(c.calls.length,0);});
