test('RSS parser accepts one exact C UTC row and refuses ownership, grammar and memory overflow',async()=>{const h=await harness(),row='123 456 1024 Fri Nov  6 12:13:14 2026\n';assert.deepEqual(plain(h.parseRss(Buffer.from(row),123,456,null)),{rssBytes:1048576,startWitness:'Fri Nov  6 12:13:14 2026'});for(const text of [row+row,row.replace('123','124'),row.replace('456','457'),row.replace('1024','1.5'),row.replace('Fri','XXX'),row.replace('1024','9999999999999999999999')])assert.throws(()=>h.parseRss(Buffer.from(text),123,456,null),/timeline-owner-rss/);assert.throws(()=>h.parseRss(Buffer.from(row),123,456,'other'),/timeline-owner-rss/);});
test('closed child result schema rejects extra keys and invalid null, policy, identity and flags joins',async()=>{const h=await harness(),ref={path:id.id+'/'+P.storage.rawFilename,bytes:2,sha256:sha('{}')},r=invalid(ref);assert.deepEqual(plain(h.validateResult(r,id,ref)),r);for(const mutate of [r=>r.events=[],r=>r.costs={},r=>r.identity=id,r=>r.policySha256='0'.repeat(64),r=>r.performance=true,r=>r.rawReference.bytes++]){const x=plain(r);mutate(x);assert.throws(()=>h.validateResult(x,id,ref),/timeline-owner-result/);}});

// Authored event/OS model, isolated to this test. No production constructor ports.
async function model(t,mode='okay',overrides={}){
 const {EventEmitter}=await import('node:events'),{PassThrough,Writable}=await import('node:stream');
 const c=await context(t),state={now:1000,children:[],signals:[],queries:[],dispatches:[],reads:[],timers:new Set(),queryMode:overrides.queryMode??'okay'};
 c.input.caseStarted=1000;c.input.invocationStarted=1000;
 function schedule(fn,delay){const x={fn,due:state.now+delay};state.timers.add(x);return x;}
 function cancel(x){state.timers.delete(x);}
 async function flush(){for(let i=0;i<40;i++)await new Promise(r=>setImmediate(r));}
 async function advance(ms){state.now+=ms;const due=[...state.timers].filter(x=>x.due<=state.now);for(const x of due)if(state.timers.delete(x))x.fn();await flush();}
 function finish(p,code=0,signal=null){if(p.done)return;p.done=true;if(overrides.missingExitFor!==(p.pid===500?'decoder':'rss-query'))p.emit('exit',code,signal);p.stdout.end();p.stderr.end();if(!p.stdin.writableEnded)p.stdin.end();setImmediate(()=>setImmediate(()=>p.emit('close',code,signal)));}
 function spawnModel(executable,args,options){
  state.dispatches.push({executable,args:plain(args),options:plain(options),at:state.now});const p=new EventEmitter();p.pid=mode==='spawn-error'?undefined:500+state.children.length;p.stdout=new PassThrough();p.stderr=new PassThrough();p.done=false;p.kill=sig=>{state.signals.push({pid:p.pid,sig,at:state.now});if(overrides.ignoreSignals!==true&&(sig==='SIGKILL'||overrides.ignoreTerm!==true))finish(p,null,sig);return true;};
  const decoder=args[0]==='--max-old-space-size=512';let incoming='';const emit=(type,body,token)=>p.stdout.write(JSON.stringify({schema:P.schemas.message,type,token,body})+'\n');
  p.stdin=new Writable({highWaterMark:overrides.highWaterMark??16384,write(bytes,encoding,cb){incoming+=bytes.toString();while(incoming.includes('\n')){const n=incoming.indexOf('\n'),f=JSON.parse(incoming.slice(0,n));incoming=incoming.slice(n+1);state.frames??=[];state.frames.push({type:f.type,at:state.now});
   if(f.type==='request'){state.request=f.body;if(mode!=='no-ready')setImmediate(()=>{if(mode==='bad-utf8')p.stdout.write(Buffer.from([255,10]));else if(mode==='duplicate-key')p.stdout.write('{"schema":1,"\\u0073chema":2}\n');else emit('ready',{pid:mode==='wrong-ready-pid'?999:p.pid},f.token);if(mode==='duplicate-ready')emit('ready',{pid:p.pid},f.token);});}
   if(f.type==='decode-ack'){const send=()=>{if(mode==='stdout-cap')p.stdout.write(Buffer.alloc(262145,32));else if(mode==='stderr-cap')p.stderr.write(Buffer.alloc(65537,32));else{const result=invalid(c.bridge.rawReference);if(mode==='result-extra')result.traceEvents=[];emit('result-ready',result,f.token);if(mode==='result-nonzero')setImmediate(()=>finish(p,7,null));if(mode==='result-signal')setImmediate(()=>finish(p,null,'SIGABRT'));if(mode==='terminal-trailing')p.stdout.write('x');}};if(mode==='wait-result')state.sendResult=send;else setImmediate(send);}
   if(f.type==='exit-ack'&&mode==='exit-nonzero')state.exitCode=7;
  }if(mode==='write-callback-pending'&&decoder){state.releaseWrite=cb;return;}if(mode==='write-callback-error'&&decoder){cb(Error('private'));return;}cb();}});
  if(decoder)p.stdin.on('finish',()=>{if(mode==='exit-hang')return;finish(p,state.exitCode??0,null);});
  for(const name of ['stdout','stderr']){const read=p[name].read.bind(p[name]);p[name].read=n=>{if(n)state.reads.push([name,n]);return read(n);};}
  state.children.push(p);setImmediate(()=>{if(mode==='spawn-error'&&decoder){p.emit('error',Error('secret'));p.pid=undefined;p.stdin.destroy();p.stdout.destroy();p.stderr.destroy();p.emit('close',null,null);return;}p.emit('spawn');if(!decoder){state.queries.push(p);const complete=()=>{let row=`500 ${process.pid} ${state.queryMode==='threshold'?1048577:1024} Fri Nov  6 12:13:14 2026\n`;if(state.queryMode==='wrong-ppid')row=row.replace(String(process.pid),'999');if(state.queryMode==='witness-change'&&state.queries.length>1)row=row.replace('12:13:14','12:13:15');if(state.queryMode==='duplicate-row')row+=row;if(state.queryMode==='malformed')row='not a row\n';if(state.queryMode==='stdout-cap')row='x'.repeat(4097);if(state.queryMode==='stderr-cap')p.stderr.write(Buffer.alloc(8193,32));p.stdout.write(row);finish(p,state.queryMode==='nonzero'?3:0,null);};if(state.queryMode==='pending')state.finishQuery=complete;else setImmediate(complete);}});return p;
 }
 const stat={dev:1n,ino:1n,size:1n,mtimeNs:1n,ctimeNs:1n,nlink:1n,isFile:()=>true,isSymbolicLink:()=>false};
 const io={async realpath(name){overrides.onFS?.('realpath',state);return name;},async lstat(){return stat;},async open(name){overrides.onFS?.('open',state);let read=0;return {async stat(){return stat;},async read(buffer,offset,length){state.reads.push(['file',length]);if(read++)return {bytesRead:0};buffer[offset]=1;return {bytesRead:1};},async close(){overrides.onFS?.('close',state);}};}};
 const h=await harness({fs:io,spawn:spawnModel,performance:{now:()=>state.now},setTimeout:schedule,clearTimeout:cancel,...overrides.ports});
 return {...c,state,h,flush,advance,finish,run:()=>h.runAimockTraceDecoderOwnerV3(c.input)};
}
test('separate model executes fixed dispatch, initial/terminal order and exact finite process/pipe originals',async t=>{const m=await model(t),original=m.run();await m.flush();const r=await original;closed(r);assert.equal(r.decoderOwner.status,'complete',JSON.stringify(r));assert.deepEqual(m.state.frames.map(x=>x.type),['request','decode-ack','exit-ack']);assert.equal(m.state.dispatches.length,3);assert.deepEqual(m.state.dispatches[0].args,[ '--max-old-space-size=512',fileURLToPath(new URL('./aimock-trace-decoder-child-v3.mjs',entry))]);for(const d of m.state.dispatches){assert.deepEqual(d.options.stdio,['pipe','pipe','pipe']);assert.equal(d.options.shell,false);assert.equal(d.options.detached,false);assert.equal(d.options.env.NODE_OPTIONS,undefined);}assert.deepEqual(m.state.dispatches[1].args,['-p','500','-o','pid=','-o','ppid=','-o','rss=','-o','lstart=']);assert.equal(m.state.dispatches[1].options.env.LC_ALL,'C');assert.equal(m.state.dispatches[1].options.env.TZ,'UTC');assert.equal(m.state.signals.length,0);assert.ok(m.state.reads.every(([,n])=>n<=65536));});
for(const mode of ['wrong-ready-pid','bad-utf8','duplicate-key','duplicate-ready','stdout-cap','stderr-cap','result-extra','result-nonzero','result-signal','exit-nonzero','terminal-trailing'])test('separate owned originals refuse '+mode+' without manufacturing success',async t=>{const m=await model(t,mode),r=await m.run();closed(r);assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderOwner.unsafeOutstanding,false);assert.ok(m.state.children.every(p=>p.done));assert.ok(m.state.reads.every(([,n])=>n<=65536));if(['result-nonzero','result-signal','exit-nonzero','terminal-trailing'].includes(mode))assert.equal(r.decoderResult.status,'invalid');else assert.equal(r.decoderResult,null);if(r.decoderOriginals){const o=m.values.get(r.decoderOriginals.path);for(const p of [o.decoder,...o.queries]){assert.ok(p.close.observedMs!==null);for(const s of ['stdin','stdout','stderr'])assert.ok(p[s].closeMs!==null);}if(mode==='stdout-cap'){assert.equal(o.decoder.stdout.observedBytes,262145);assert.equal(o.decoder.stdout.completeSha256,null);assert.equal(Buffer.from(o.decoder.stdout.retainedPrefixBase64,'base64').length,256);}if(mode==='stderr-cap'){assert.equal(o.decoder.stderr.observedBytes,65537);assert.equal(o.decoder.stderr.completeSha256,null);assert.equal(Buffer.from(o.decoder.stderr.retainedPrefixBase64,'base64').length,1024);}}});
