for(const mode of ['pending','late'])test('originals '+mode+' readback cannot expose reference or move process closure timestamp',async t=>{const m=await model(t);let release;const read=m.input.store.readJSON;m.input.store.readJSON=async(...args)=>{if(mode==='pending')return new Promise(resolve=>{release=resolve;});const dto=await read(...args);m.state.now=11000;return dto;};const original=m.run();await m.flush();if(mode==='pending')await m.advance(10000);const r=await original;assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderOriginals,null);assert.equal(r.decoderOwner.originalsReference,null);assert.equal(r.decoderOwner.clock.originalsClosedMs,1000);assert.equal(r.decoderOwner.unsafeOutstanding,mode==='pending');if(mode==='pending'){release({});await m.flush();assert.equal(r.decoderOriginals,null);}});

for(const kind of ['decoder','rss-query'])test('review: close and pipe closure without actual '+kind+' exit remains unsafe until original cleanup end',async t=>{const m=await model(t,'okay',{missingExitFor:kind}),original=m.run();await m.flush();if(kind==='rss-query')await m.advance(250);await m.advance(kind==='decoder'?10000:9750);await m.advance(260000);const r=await original,before=JSON.stringify(r);assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderOwner.unsafeOutstanding,true);assert.equal(r.decoderOwner.clock.originalsClosedMs,null);assert.equal(r.decoderOriginals,null);assert.equal(m.calls.filter(x=>x[0]==='write').length,0);const p=m.state.children.find(p=>(p.pid===500?'decoder':'rss-query')===kind);assert.ok(p.done);assert.ok(!m.state.signals.some(x=>x.pid===p.pid));p.emit('exit',0,null);await m.flush();assert.equal(JSON.stringify(r),before);});
test('review: late actual helper exit can settle unsafe originals without rescuing availability',async t=>{const m=await model(t,'okay',{missingExitFor:'rss-query'}),original=m.run();await m.flush();await m.advance(250);m.state.children.find(p=>p.pid!==500).emit('exit',0,null);await m.flush();const r=await original;assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderOwner.unsafeOutstanding,false);assert.equal(r.decoderOwner.clock.originalsClosedMs,1250);const o=m.values.get(r.decoderOriginals.path),q=o.queries[0];assert.equal(q.exit.status,'fulfilled');assert.equal(q.exit.code,0);assert.equal(q.exit.observedMs,1250);assert.equal(q.close.observedMs,1000);assert.equal(r.decoderOwner.rss.rejected,1);assert.equal(r.decoderOwner.rss.pending,0);});
test('review: rejected spawn without acquired PID needs no fabricated exit and is safely closed',async t=>{const m=await model(t,'spawn-error'),r=await m.run();assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderOwner.unsafeOutstanding,false);assert.equal(m.state.signals.length,0);const o=m.values.get(r.decoderOriginals.path);assert.equal(o.decoder.pid,null);assert.equal(o.decoder.spawn.status,'rejected');assert.equal(o.decoder.exit.observedMs,null);assert.equal(o.decoder.exit.code,null);});
for(const change of ['thread-overcount','thread-first8-repeat','thread-latest-order','frame-record-repeat','frame-order','frame-thread-same-event','cost-cross-class','cost-metadata-index','population-total'])test('review: parent refuses impossible bounded aggregate '+change,async()=>{const h=await harness(),ref={path:id.id+'/'+P.storage.rawFilename,bytes:2,sha256:sha('{}')},v=valid(ref),w=v.rendererMapping.threadWitnesses,f=v.rendererMapping.frameWitnesses;
 if(change==='thread-overcount'){w.totalCount=9;w.duplicateCount=8;w.first8=Array.from({length:8},()=>({...w.latest}));w.retainedCount=9;w.droppedCount=0;w.truncated=false;}
 if(change==='thread-first8-repeat'){w.totalCount=2;w.duplicateCount=1;w.first8.push({...w.latest});w.retainedCount=2;}
 if(change==='thread-latest-order'){v.traceEventCount=20;w.totalCount=10;w.duplicateCount=9;w.first8=Array.from({length:8},(_,i)=>({...w.latest,eventIndex:i+1}));w.latest={...w.latest,eventIndex:7};w.retainedCount=9;w.droppedCount=1;w.truncated=true;}
 if(change==='frame-record-repeat'){f.totalCount=2;f.duplicateCount=1;f.first8.push({...f.latest});f.retainedCount=2;}
 if(change==='frame-order'){v.traceEventCount=20;f.totalCount=10;f.duplicateCount=9;f.first8=Array.from({length:8},(_,i)=>({...f.latest,frameRecordIndex:i}));f.latest={...f.latest,frameRecordIndex:6};f.retainedCount=9;f.droppedCount=1;f.truncated=true;}
 if(change==='frame-thread-same-event'){w.first8[0].eventIndex=0;w.latest.eventIndex=0;v.rendererMapping.binding.threadEventIndex=0;}
 if(change==='cost-cross-class')v.costs.layouts={observedCompleteEvents:1,longest:[{...v.costs.tasks.longest[0]}]};
 if(change==='cost-metadata-index')v.costs.tasks.longest[0].eventIndex=1;
 if(change==='population-total'){v.traceEventCount=20;for(const [i,k]of ['tasks','layouts','minorGC'].entries()){v.costs[k].observedCompleteEvents=9;v.costs[k].longest=Array.from({length:8},(_,j)=>({eventIndex:2+i*8+j,timestampUs:0,durationUs:50000-j}));}v.traceEventCount=30;v.costs.tasks.observedCompleteEvents=15;v.costs.tasks.longTaskEvents=1;v.costs.layouts.observedCompleteEvents=15;v.costs.minorGC.observedCompleteEvents=15;}
 assert.throws(()=>h.validateResult(v,id,ref),/timeline-owner-result/);
});
test('review: multiple frame records in one event remain valid even when frame total exceeds event count',async()=>{const h=await harness(),ref={path:id.id+'/'+P.storage.rawFilename,bytes:2,sha256:sha('{}')},v=valid(ref),f=v.rendererMapping.frameWitnesses;f.totalCount=9;f.duplicateCount=8;f.first8=Array.from({length:8},(_,i)=>({...f.latest,frameRecordIndex:i}));f.latest={...f.latest,frameRecordIndex:8};f.retainedCount=9;assert.equal(h.validateResult(v,id,ref),v);});

test('race: result-ready waits exact active tick sample through parsing and finally after helper close',async t=>{const m=await model(t,'wait-result'),original=m.run();await m.flush();m.state.queryMode='pending';await m.advance(100);assert.equal(m.state.queries.length,2);m.state.queryMode='okay';m.state.sendResult();m.state.finishQuery();await m.flush();const r=await original;assert.equal(r.decoderOwner.status,'complete',JSON.stringify(r.decoderOwner));assert.deepEqual(r.decoderOwner.rss.samples.map(row=>row[0]),[0,1,2]);assert.equal(r.decoderOwner.rss.attempted,3);assert.equal(r.decoderOwner.rss.fulfilled,3);assert.equal(r.decoderOwner.rss.pending,0);assert.equal(r.decoderOwner.rss.rejected,0);assert.equal(r.decoderOwner.rss.missed,0);assert.equal(r.decoderOwner.rss.terminalSeen,true);assert.deepEqual(m.state.frames.map(f=>f.type),['request','decode-ack','exit-ack']);});
test('race: result-ready cannot hide failed active tick sample or launch terminal/exit ack',async t=>{const m=await model(t,'wait-result'),original=m.run();await m.flush();m.state.queryMode='pending';await m.advance(100);m.state.sendResult();m.state.queryMode='malformed';m.state.finishQuery();await m.flush();const r=await original;assert.equal(r.decoderOwner.status,'unavailable');assert.equal(r.decoderResult.status,'invalid');assert.equal(r.decoderOwner.rss.attempted,2);assert.equal(r.decoderOwner.rss.fulfilled,1);assert.equal(r.decoderOwner.rss.rejected,1);assert.equal(r.decoderOwner.rss.terminalSeen,false);assert.equal(r.decoderOwner.unsafeOutstanding,false);assert.deepEqual(m.state.frames.map(f=>f.type),['request','decode-ack']);});

test('stock037 format owner recognizes authored Threadplane identity',async()=>{
 const h=await harness(),identity={...id,profile:'threadplane',stockVersion:'0.3.7'};
 assert.doesNotThrow(()=>h.validateIdentity(identity));
 for(const [profile,stockVersion]of [['threadplane','0.3.8'],['threadplane',null],['assistant-ui','0.3.7'],['vercel-ai',null]])assert.throws(()=>h.validateIdentity({...identity,profile,stockVersion}),/timeline-owner-arguments/);
});
